package dev.podjs.runtime;
import static org.junit.Assert.*;
import android.bluetooth.*;
import android.graphics.Bitmap;
import android.os.Bundle;
import androidx.test.platform.app.InstrumentationRegistry;
import org.json.*;
import org.junit.Test;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicBoolean;
/** Bonded public main-app fixture; sends only read-only probes and session completion. */
public final class WatchRssIpMainProbeTest {
 private static final String UUID_VALUE="bb2f0b7d-8f2f-4a96-95b2-d2c91d58a861";
 private DataInputStream input;private DataOutputStream output;private int actions;
 @Test public void mainProbeIsAuthenticatedAndReadOnly()throws Exception{
  String address=InstrumentationRegistry.getArguments().getString("watchAddress");assertNotNull(address);
  BluetoothAdapter adapter=InstrumentationRegistry.getInstrumentation().getTargetContext().getSystemService(BluetoothManager.class).getAdapter();assertNotNull(adapter);assertTrue(adapter.isEnabled());BluetoothDevice device=adapter.getRemoteDevice(address);assertEquals(BluetoothDevice.BOND_BONDED,device.getBondState());
  AtomicBoolean timedOut=new AtomicBoolean();ScheduledExecutorService watchdog=Executors.newSingleThreadScheduledExecutor();ExecutorService handshake=Executors.newSingleThreadExecutor();
  Bundle args=InstrumentationRegistry.getArguments();int listenPort=Integer.parseInt(args.getString("listenPort","45077")),endpointPort=Integer.parseInt(args.getString("endpointPort","45077"));String endpointAddress=args.getString("endpointAddress"),routeKind=args.getString("routeKind","wifiLan");assertNotNull(endpointAddress);boolean dropFirst=args.getString("dropFirstRoute","false").equals("true");
  try(PodWebSocketServicesTest.Server server=new PodWebSocketServicesTest.Server("0.0.0.0",listenPort)){
   server.listener.setSoTimeout(150000);watchdog.schedule(()->{timedOut.set(true);try{server.close();}catch(Exception ignored){}},150,TimeUnit.SECONDS);
   byte[] secretBytes=new byte[16];new java.security.SecureRandom().nextBytes(secretBytes);String secret=Base64.getUrlEncoder().encodeToString(secretBytes),challenge="ip-main-probe-challenge";long expires=System.currentTimeMillis()+120000;int priority=routeKind.equals("wifiLan")?300:50;
   JSONObject endpoint=new JSONObject().put("endpointId","ip-peer").put("address",endpointAddress).put("family","ipv4").put("transportKind",routeKind).put("priority",priority);
   JSONObject descriptor=new JSONObject().put("version",2).put("serverDeviceId","ip-main-probe-phone").put("epoch",7).put("expiresAt",expires).put("port",endpointPort).put("endpoints",new JSONArray().put(endpoint)).put("challengeId",challenge).put("challengeSecret",secret);
   descriptor.put("hmac",mac(secret,"2|ip-main-probe-phone|7|"+expires+"|"+endpointPort+"|ip-peer,"+endpointAddress+",ipv4,"+routeKind+","+priority+";|"+challenge+"|"+secret));
   Future<String> authenticated=handshake.submit(()->{for(int attempt=0;attempt<(dropFirst?2:1);attempt++){server.accept();server.socket.setSoTimeout(150000);JSONObject hello=new JSONObject(new String(server.read(1),StandardCharsets.UTF_8));assertEquals("hello",hello.getString("type"));assertEquals(2,hello.getInt("version"));assertEquals(challenge,hello.getString("challengeId"));assertEquals(7,hello.getLong("endpointEpoch"));assertEquals(0,hello.getLong("lastAckSeq"));assertFalse(hello.getString("clientNonce").isEmpty());String watch=hello.getString("watchDeviceId");assertFalse(watch.isEmpty());assertEquals(mac(secret,"2|"+watch+"|"+challenge+"|7|"+hello.getString("clientNonce")+"||0"),hello.getString("hmac"));JSONObject ack=new JSONObject().put("type","helloAck").put("serverDeviceId","ip-main-probe-phone").put("sessionId","ip-peer-session").put("routeKind",routeKind).put("acceptedResumeSeq",0).put("serverNonce","ip-peer-nonce").put("hmac",mac(secret,"2|ip-main-probe-phone|ip-peer-session|"+routeKind+"|0|ip-peer-nonce"));server.send(1,ack.toString().getBytes(StandardCharsets.UTF_8));if(dropFirst&&attempt==0){server.socket.close();continue;}return watch;}throw new AssertionError("No authenticated route");});
   try(BluetoothSocket bootstrap=device.createRfcommSocketToServiceRecord(UUID.fromString(UUID_VALUE))){bootstrap.connect();input=new DataInputStream(bootstrap.getInputStream());output=new DataOutputStream(bootstrap.getOutputStream());write(new JSONObject().put("action","syncLibrary").put("phase","probe").put("version",14).put("ipEndpointDescriptor",descriptor));JSONObject accepted=read();assertTrue(accepted.toString(),accepted.getBoolean("ipUpgradeAccepted"));write(new JSONObject().put("action","ack").put("success",true).put("applied",true));}
   String authenticatedWatchId=authenticated.get(10,TimeUnit.SECONDS);
   input=new DataInputStream(new InputStream(){byte[] buffered=new byte[0];int at;public int read()throws IOException{byte[] b=new byte[1];int n=read(b,0,1);return n<0?-1:b[0]&255;}public int read(byte[] bytes,int offset,int length)throws IOException{if(length==0)return 0;while(at==buffered.length){try{buffered=server.read(2);at=0;}catch(EOFException end){return -1;}catch(Exception error){throw new IOException(error);}}int n=Math.min(length,buffered.length-at);System.arraycopy(buffered,at,bytes,offset,n);at+=n;return n;}});
   output=new DataOutputStream(new OutputStream(){public void write(int value)throws IOException{write(new byte[]{(byte)value},0,1);}public void write(byte[] bytes,int offset,int count)throws IOException{try{server.send(2,Arrays.copyOfRange(bytes,offset,offset+count));}catch(Exception error){throw new IOException(error);}}});
   String expected=InstrumentationRegistry.getArguments().getString("expectedWatchId");assertNotNull(expected);assertEquals(expected,authenticatedWatchId);
   for(int i=0;i<2;i++){write(new JSONObject().put("action","syncLibrary").put("version",14).put("phase","probe").put("requestPersistentSession",i==0).put("supportsPersistentSession",true));JSONObject response=read();assertTrue(response.getBoolean("success"));assertEquals(expected,response.getString("deviceId"));assertEquals(14,response.getInt("version"));assertEquals("probe",response.getString("phase"));if(i==0)assertTrue(response.getBoolean("persistentSessionAccepted"));write(new JSONObject().put("action","ack").put("success",true).put("applied",true));}
   boolean tokenProbe=args.getString("tokenUsageProbe","false").equals("true");int tokenRecords=-1;
   if(tokenProbe){JSONArray expectedIds=new JSONArray(args.getString("expectedTokenIds"));for(int limit:new int[]{200,0,-1}){JSONObject request=new JSONObject().put("action","syncLlmTokenUsage");if(limit!=200)request.put("limit",limit);write(request);JSONObject response=read();assertTrue(response.toString(),response.getBoolean("success"));assertEquals("syncLlmTokenUsage",response.getString("action"));JSONArray records=response.getJSONArray("records");int count=limit<0?expectedIds.length():Math.min(limit,expectedIds.length());assertEquals(count,response.getInt("count"));assertEquals(count,records.length());for(int i=0;i<count;i++){JSONObject row=records.getJSONObject(i);assertEquals(expectedIds.getLong(i),row.getLong("id"));assertTrue(row.has("provider")&&row.has("model")&&row.has("requestId")&&row.has("createdAt"));assertFalse(row.has("usage_json"));}if(limit<0)tokenRecords=count;write(new JSONObject().put("action","ack").put("success",true).put("applied",true));}}
   boolean readerProbe=args.getString("readerManifestProbe","false").equals("true");int readerPresets=-1;
   if(readerProbe){JSONObject expectedReader=new JSONObject(new String(Base64.getDecoder().decode(args.getString("expectedReaderBase64")),StandardCharsets.UTF_8));write(new JSONObject().put("action","syncReader").put("phase","manifest"));JSONObject response=read();assertTrue(response.toString(),response.getBoolean("success"));assertEquals("syncReader",response.getString("action"));assertEquals("manifest",response.getString("phase"));assertEquals(11,response.getInt("version"));for(String kind:new String[]{"presets","fonts","backgrounds","deletions"}){JSONArray rows=response.getJSONArray(kind),ids=expectedReader.getJSONArray(kind);assertEquals(ids.length(),rows.length());for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);assertEquals(ids.getString(i),kind.equals("deletions")?row.getString("kind")+"/"+row.getString("entityId"):row.getString("id"));}}readerPresets=response.getJSONArray("presets").length();assertTrue(response.has("missingResources"));write(new JSONObject().put("action","ack").put("success",true).put("applied",true));}
   boolean previewProbe=args.getString("readerPreviewProbe","false").equals("true");int previewRequests=0;
   if(previewProbe){String previewId="phone-preview-"+UUID.randomUUID();JSONObject preset=new JSONObject().put("schemaVersion",2).put("id","ephemeral-preview").put("name","Phone preview");JSONArray requests=new JSONArray().put(new JSONObject().put("phase","update").put("sequence",0).put("preset",preset)).put(new JSONObject().put("phase","heartbeat").put("sequence",1)).put(new JSONObject().put("phase","update").put("sequence",2).put("changes",new JSONObject().put("name","Preview updated"))).put(new JSONObject().put("phase","resourceHandoff").put("sequence",3).put("preset",preset)).put(new JSONObject().put("phase","update").put("sequence",4).put("preset",preset)).put(new JSONObject().put("phase","stop")).put(new JSONObject().put("phase","stop"));for(int index=0;index<requests.length();index++){JSONObject request=requests.getJSONObject(index).put("action","previewReader").put("version",2).put("sessionId",previewId);write(request);JSONObject response=read();assertTrue(response.toString(),response.getBoolean("success"));assertEquals("previewReader",response.getString("action"));assertEquals(previewId,response.getString("sessionId"));assertEquals(request.getString("phase"),response.getString("phase"));if(index==1)assertEquals(1,response.getLong("appliedSequence"));else assertEquals(index!=6,response.getBoolean("applied"));write(new JSONObject().put("action","ack").put("success",true).put("applied",true));previewRequests++;}}
   write(new JSONObject().put("action","syncSession").put("phase","complete"));assertEquals("complete",read().getString("phase"));write(new JSONObject().put("action","ack").put("success",true).put("applied",true));assertEquals(-1,input.read());assertFalse(timedOut.get());
   Bundle proof=new Bundle();proof.putString("ipMainProbeProof",new JSONObject().put("readerPreviewProbed",previewProbe).put("readerPreviewRequests",previewRequests).put("readerManifestProbed",readerProbe).put("readerPresets",readerPresets).put("tokenUsageProbed",tokenProbe).put("tokenUsageRequests",tokenProbe?3:0).put("tokenUsageRecords",tokenRecords).put("watchId",authenticatedWatchId).put("readOnly",true).put("probes",2).put("handshakes",dropFirst?2:1).put("droppedFirstRoute",dropFirst).put("authenticated",true).put("bootstrapAccepted",true).put("routeKind",routeKind).put("endpointAddress",endpointAddress).put("adbRelay",args.getString("adbRelay","false").equals("true")).toString());InstrumentationRegistry.getInstrumentation().sendStatus(0,proof);
  }finally{watchdog.shutdownNow();handshake.shutdownNow();}
 }
 private static String mac(String key,String text)throws Exception{javax.crypto.Mac mac=javax.crypto.Mac.getInstance("HmacSHA256");mac.init(new javax.crypto.spec.SecretKeySpec(Base64.getUrlDecoder().decode(key),"HmacSHA256"));return Base64.getUrlEncoder().encodeToString(mac.doFinal(text.getBytes(StandardCharsets.UTF_8)));}
 private JSONObject read()throws Exception{int n=input.readInt();assertTrue(n>0&&n<=2*1024*1024);byte[] b=new byte[n];input.readFully(b);return new JSONObject(new String(b,StandardCharsets.UTF_8));}
 private void write(JSONObject value)throws Exception{byte[] b=value.toString().getBytes(StandardCharsets.UTF_8);output.writeInt(b.length);output.write(b);output.flush();}
 private static String hash(byte[] b)throws Exception{StringBuilder s=new StringBuilder();for(byte v:MessageDigest.getInstance("SHA-256").digest(b))s.append(String.format(Locale.ROOT,"%02x",v&255));return s.toString();}
}
